q = zip(map(int, input().split()), map(int, input().split()))
n = int(input())
c = list(map(int, input().split()))
d = c[:]
for (k, t) in q:
	for i in range(min(k, n)):
		c[i] += t
	for i in range(k, n):
		c[i] = max(c[i], c[i - k]) + t
print(max((c[i] - d[i] for i in range(n))))
